<?php if(($pages??1)>1):$makeUrl=function(int $target){$query=$_GET;$query['page']=$target;return '?'.http_build_query($query);};$visible=array_unique(array_filter([1,$page-2,$page-1,$page,$page+1,$page+2,$pages],fn($p)=>$p>=1&&$p<=$pages));sort($visible);?><nav class="pagination" aria-label="Paginare"><a class="page-arrow <?=$page<=1?'disabled':''?>" href="<?=$page>1?e($makeUrl($page-1)):'#'?>" aria-label="Pagina precedentă">←</a><?php $previous=0;foreach($visible as $number):if($previous&&$number>$previous+1):?><span>…</span><?php endif?><a href="<?=e($makeUrl($number))?>" <?=$number===$page?'aria-current="page"':''?>><?=$number?></a><?php $previous=$number;endforeach?><a class="page-arrow <?=$page>=$pages?'disabled':''?>" href="<?=$page<$pages?e($makeUrl($page+1)):'#'?>" aria-label="Pagina următoare">→</a></nav><?php endif?>
